#pragma warning disable IDE0130

namespace SOS
{
    /// <summary>
    /// Provides helper methods for filtering prefabs based on search criteria.
    /// </summary>
    /// <remarks>
    /// Contains static methods for matching prefabs against filter criteria. Used by the prefab browser
    /// to filter the list of displayed prefabs based on user input.
    /// </remarks>
    public static class PrefabFilterHelper
    {
        /// <summary>
        /// Checks if a prefab matches the general filter criteria.
        /// </summary>
        /// <param name="filter">The filter containing the general search terms.</param>
        /// <param name="name">The prefab's display name.</param>
        /// <param name="identifier">The prefab's identifier.</param>
        /// <param name="modName">The mod name the prefab belongs to.</param>
        /// <returns><c>true</c> if the prefab matches all general filter terms; <c>false</c> otherwise.</returns>
        /// <remarks>
        /// If the filter's <see cref="ISOSPrefabFilter.General"/> list is empty, the method returns <c>true</c> immediately.
        /// For each term in the general filter, the method checks if the term is contained in the name, identifier, or mod name
        /// (case-insensitive). If any term is not found in any of the three fields, the method returns <c>false</c>.
        /// </remarks>
        public static bool MatchesGeneral(ISOSPrefabFilter filter, string name, string identifier, string modName)
        {
            if (filter.General.Count == 0) return true;

            foreach (var term in filter.General)
            {
                if (name.Contains(term, StringComparison.OrdinalIgnoreCase)) continue;
                if (identifier.Contains(term, StringComparison.OrdinalIgnoreCase)) continue;
                if (modName.Contains(term, StringComparison.OrdinalIgnoreCase)) continue;
                return false;
            }

            return true;
        }
    }

    /// <summary>
    /// Represents a parsed search filter for prefabs, supporting typed search terms.
    /// </summary>
    /// <remarks>
    /// The filter is constructed from a raw query string that may contain typed prefixes:
    /// <list type="bullet">
    /// <item><term>@</term><description>Mod filter (e.g., @MyMod)</description></item>
    /// <item><term>#</term><description>Category filter (e.g., #Weapon)</description></item>
    /// <item><term>$</term><description>Tag filter (e.g., $Radioactive)</description></item>
    /// <item><term>&amp;</term><description>Slot filter (e.g., &amp;Hand)</description></item>
    /// <item><term>!</term><description>ID filter (e.g., !my_item)</description></item>
    /// <item><term>%</term><description>Prefab type filter (e.g., %Item)</description></item>
    /// <item><term>(none)</term><description>General filter (matches name, identifier, mod name)</description></item>
    /// </list>
    /// The query is parsed by detecting these prefixes and splitting the query at each prefix character.
    /// </remarks>
    internal class SearchFilter : ISOSPrefabFilter
    {
        public List<string> General { get; } = [];
        public List<string> Mod { get; } = [];
        public List<string> Category { get; } = [];
        public List<string> Tag { get; } = [];
        public List<string> Slot { get; } = [];
        public List<string> ID { get; } = [];
        public List<string> PrefabType { get; } = [];

        /// <summary>
        /// Parses a raw query string into a structured search filter.
        /// </summary>
        /// <param name="rawQuery">The raw search query string. Can be null or empty.</param>
        /// <remarks>
        /// The parser detects typed prefixes (@, #, $, &amp;, !, %) and splits the query at each prefix.
        /// Terms without a prefix are added to the General list. If the query is null or empty,
        /// all filter lists remain empty.
        /// </remarks>
        public SearchFilter(string rawQuery)
        {
            if (string.IsNullOrWhiteSpace(rawQuery)) return;

            char currentType = ' ';
            int startIndex = 0;
            string query = rawQuery + " ";

            for (int i = 0; i < query.Length; i++)
            {
                char c = query[i];
                if (c == '@' || c == '#' || c == '$' || c == '&' || c == '!' || c == '%' || i == query.Length - 1)
                {
                    string content = query[startIndex..i].Trim();
                    if (!string.IsNullOrEmpty(content))
                    {
                        switch (currentType)
                        {
                            case ' ': General.Add(content); break;
                            case '@': Mod.Add(content); break;
                            case '#': Category.Add(content); break;
                            case '$': Tag.Add(content); break;
                            case '&': Slot.Add(content); break;
                            case '!': ID.Add(content); break;
                            case '%': PrefabType.Add(content); break;
                        }
                    }
                    currentType = c;
                    startIndex = i + 1;
                }
            }
        }

        /// <summary>
        /// Checks if a prefab type name matches the prefab type filter.
        /// </summary>
        /// <param name="name">The prefab type name to check.</param>
        /// <returns><c>true</c> if the type is allowed by the filter; <c>false</c> otherwise.</returns>
        /// <remarks>
        /// If the <see cref="ISOSPrefabFilter.PrefabType"/> list is empty, all types are allowed.
        /// Otherwise, the type name is checked against each term in the PrefabType list using
        /// case-insensitive containment matching.
        /// </remarks>
        internal bool AllowsType(string name)
            => PrefabType.Count == 0 || PrefabType.Any(t => name.Contains(t, StringComparison.OrdinalIgnoreCase));
    }
}
